import { describe, expect, test } from "bun:test";
import chalk from "chalk";
import { buildAttributionAndOwned, toBaseline } from "../deployment.js";
import type { DesiredEntityType, DesiredState } from "../desired-state.js";
import {
  type Baseline,
  computeDiff,
  ownedKey,
  type RemoteSnapshot,
} from "../diff.js";

chalk.level = 0;

function buildState(entityTypes: DesiredEntityType[]): DesiredState {
  return {
    agents: [],
    prune: false,
    memorySchema: { entityTypes, relationshipTypes: [] },
    watchers: [],
    connectors: { definitions: [], authProfiles: [], connections: [] },
    providers: [],
    requiredSecrets: [],
  };
}

function emptyRemote(): RemoteSnapshot {
  return {
    agents: [],
    agentSettings: new Map(),
    entityTypes: [],
    relationshipTypes: [],
    watchers: [],
    connectorDefinitions: [],
    authProfiles: [],
    connections: [],
    feedsByConnectionId: new Map(),
    inferenceProviders: [],
  };
}

function taskType(
  overrides: Partial<DesiredEntityType> = {}
): DesiredEntityType {
  return {
    slug: "task",
    name: "Task",
    required: ["status"],
    properties: {
      status: {
        type: "string",
        enum: ["backlog", "active", "done"],
      },
    },
    ...overrides,
