/** Classify a remote-only definition without deleting unproven ownership. */
function remoteOnlyDefinitionRow(
  kind: "entity-type" | "relationship-type" | "watcher",
  remote: { slug: string; id?: number | string },
  baseline: Baseline | undefined,
  prune: boolean,
  unchangedSinceBaseline: (slug: string) => boolean
): DiffRow {
  // Prune off: this apply deletes nothing, so an un-declared definition is news
  // rather than a hazard — report it and let the rest of the plan run. Blocking
  // here protected nothing and stalled every later apply until a human adopted
  // or removed the definition. Connector definitions already work this way
  // (their delete/block pair lives inside `if (prune && …)`).
  if (!prune) {
    return { kind, verb: "drift", id: remote.slug, remote } as DiffRow;
  }
  // Prune on: delete only an incarnation a RECORDED baseline proves this config
  // created and nobody has edited since. Unowned (UI-created), edited, or
  // unprovable-because-unrecorded all block instead — deleting the wrong
  // definition is unrecoverable.
  const owned =
    baseline?.recorded === true &&
    remote.id !== undefined &&
    baseline.owned.has(ownedKey(kind, remote.id));
  if (owned && unchangedSinceBaseline(remote.slug)) {
    return { kind, verb: "delete", id: remote.slug, remote } as DiffRow;
  }
  return {
    kind,
    verb: "drift",
    blocking: true,
    id: remote.slug,
    remote,
  } as DiffRow;
}

