function buildDiffRow<D, R, K extends string>(opts: {
  kind: K;
  id: string;
  desired: D;
  remote: R | undefined;
  fields: ReadonlyArray<DiffField<D, R>>;
  extras?: Record<string, unknown>;
  updateExtras?: (changed: string[]) => Record<string, unknown>;
}): {
  kind: K;
  verb: DiffVerb;
  id: string;
  desired: D;
  remote?: R;
  changedFields?: string[];
} & Record<string, unknown> {
  const extras = opts.extras ?? {};
  if (!opts.remote) {
    return {
      kind: opts.kind,
      verb: "create",
      id: opts.id,
      desired: opts.desired,
      ...extras,
    };
  }
  const remote = opts.remote;
  const changed = opts.fields
    .filter((f) => f.changed(opts.desired, remote))
    .map((f) => f.name);
  if (changed.length === 0) {
    return {
      kind: opts.kind,
      verb: "noop",
      id: opts.id,
      desired: opts.desired,
      remote,
      ...extras,
    };
  }
  return {
    kind: opts.kind,
    verb: "update",
    id: opts.id,
    desired: opts.desired,
    remote,
    changedFields: changed,
    ...extras,
    ...(opts.updateExtras?.(changed) ?? {}),
  };
}

