function blockedValue(value: unknown, absentLabel: string): string {
  if (value === undefined) return chalk.dim(absentLabel);
  let text: string;
  try {
    text = JSON.stringify(value, null, 2) ?? String(value);
  } catch {
    text = String(value);
  }
  return text.split("\n").join("\n    ");
}

